-- Generated by model/lib/sql/generate.mjs. Loads IMPORT Trade Fees from cells/IMPORT Trade Fees.csv in the folder of input cells. Two rows for one cell add up.
INSERT OR REPLACE INTO "IMPORT Trade Fees" SELECT coalesce(k0."Customer Group", error('cells name a member Customer Group does not have: ' || c."Customer Group")), coalesce(k1."Brand", error('cells name a member Brand does not have: ' || c."Brand")), coalesce(k2."Years", error('cells name a member Years does not have: ' || c."Years")), coalesce(k3."Months", error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE)
FROM read_csv('cells/IMPORT Trade Fees.csv', header = true, all_varchar = true) c LEFT JOIN "dim Customer Group" k0 ON k0.name = c."Customer Group" LEFT JOIN "dim Brand" k1 ON k1.name = c."Brand" LEFT JOIN "dim Years" k2 ON k2.name = c."Years" LEFT JOIN "dim Months" k3 ON k3.name = c."Months"
GROUP BY ALL;
